/**
 * Flags emoji pages that still carry the batch template's language.
 *
 * Why this exists
 * ---------------
 * A large batch of the emoji catalog was generated by running one page
 * template over the whole list. The template satisfied the deep-tier word
 * and FAQ thresholds, so every generated page was stamped
 * `contentTier: "deep"` and every one of them shipped a FAQ array — which
 * made 1,632 near-duplicate pages look like 1,632 original articles.
 *
 * The template cannot be un-stamped by hand: the pages have to be rewritten
 * about their own emoji, and there are far more of them than there is time
 * to rewrite. So the pages are kept out of the index
 * (`src/lib/seo-policy.ts`) and out of the sitemap
 * (`src/lib/sitemap-entries.ts`), and this script tracks the backlog that
 * is left.
 *
 * What this does
 * --------------
 * It scans every emoji record for the markers the template leaves behind
 * and reports how many pages still carry them, broken down by marker. The
 * `--strict` flag turns the report into a ratchet: the run fails when the
 * number of templated pages grows, so the template cannot be reintroduced
 * by a future generator run.
 *
 * Usage:
 *   bun run check:emoji-template                # report the backlog
 *   bun run check:emoji-template -- --strict    # exit 1 when the backlog grows
 *   bun run check:emoji-template -- --top 40    # print more slugs
 *   bun run check:emoji-template -- --list      # print every templated slug
 */

import fs from 'fs';
import path from 'path';

import { getAllEmojis } from '../src/lib/emoji-data';
import { findEmojiTemplateMarkers } from '../src/lib/emoji-boilerplate';
import type { Emoji } from '../src/types/emoji';
import type { EmojiTemplateMarkerKind } from '../src/lib/emoji-boilerplate';

/**
 * The number of templated emoji pages the catalog is allowed to carry.
 *
 * Lower this as pages are rewritten about their own emoji. The ratchet only
 * fails when the count grows, so a rewrite that is not yet reflected here
 * cannot break CI.
 */
const BASELINE_TEMPLATED_EMOJI_COUNT = 1327;

interface Args {
  strict: boolean;
  top: number;
  list: boolean;
}

function parseArgs(argv: string[]): Args {
  let strict = false;
  let top = 25;
  let list = false;

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--strict') {
      strict = true;
    } else if (arg === '--list') {
      list = true;
    } else if (arg === '--top') {
      const value = Number(argv[i + 1]);
      if (Number.isFinite(value) && value > 0) {
        top = value;
        i += 1;
      }
    }
  }

  return { strict, top, list };
}

/**
 * A stable label for each kind of marker, so the report groups by rule
 * rather than by the exact number of "-coded" compounds a page happens to
 * carry.
 */
function markerLabel(kind: EmojiTemplateMarkerKind): string {
  switch (kind) {
    case 'overview-phrase':
      return 'overview says "is the emoji of"';
    case 'faq-phrase':
      return 'FAQ says "is a natural fit for"';
    case 'coded-token':
      return 'long-form is saturated with "-coded"';
    default:
      return kind;
  }
}

function main() {
  const { strict, top, list } = parseArgs(process.argv.slice(2));
  const emojis = getAllEmojis();

  const templated: { emoji: Emoji; markers: string[] }[] = [];
  const markerCounts = new Map<string, number>();

  for (const emoji of emojis) {
    const findings = findEmojiTemplateMarkers(emoji);
    if (findings.length === 0) continue;

    templated.push({
      emoji,
      markers: findings.map((finding) => markerLabel(finding.kind)),
    });

    for (const label of new Set(findings.map((finding) => markerLabel(finding.kind)))) {
      markerCounts.set(label, (markerCounts.get(label) ?? 0) + 1);
    }
  }

  console.log('');
  console.log(`Emoji pages scanned: ${emojis.length}.`);
  console.log(`Emoji pages still carrying template language: ${templated.length}.`);

  if (markerCounts.size > 0) {
    console.log('');
    console.log('By marker:');
    for (const [marker, count] of [...markerCounts.entries()].sort((a, b) => b[1] - a[1])) {
      console.log(`  ${String(count).padStart(5)}  ${marker}`);
    }
  }

  if (templated.length > 0) {
    console.log('');
    console.log('Rewrite these about their own emoji (they are noindex until they are rewritten):');
    const shown = list ? templated : templated.slice(0, top);
    for (const entry of shown) {
      console.log(`  ${entry.emoji.slug}  [${entry.markers.join(', ')}]`);
    }
    if (!list && templated.length > shown.length) {
      console.log(`  ... and ${templated.length - shown.length} more (use --list to see them all)`);
    }
  }

  if (!strict) return;

  const delta = templated.length - BASELINE_TEMPLATED_EMOJI_COUNT;
  if (delta > 0) {
    console.error('');
    console.error(
      `${templated.length} emoji page(s) carry template language, ${delta} more than the recorded ` +
        `baseline of ${BASELINE_TEMPLATED_EMOJI_COUNT}. Rewrite the copy, or lower ` +
        `BASELINE_TEMPLATED_EMOJI_COUNT in scripts/check-emoji-template.ts.`
    );
    process.exit(1);
  }

  if (delta < 0) {
    console.log('');
    console.log(
      `${-delta} templated page(s) below the recorded baseline of ` +
        `${BASELINE_TEMPLATED_EMOJI_COUNT}. Lower BASELINE_TEMPLATED_EMOJI_COUNT in ` +
        `scripts/check-emoji-template.ts to keep the ratchet tight.`
    );
  }
}

if (import.meta.main) {
  main();
}
